class EventArgs:
    """Event data passed to handlers: X, Y, Button, Delta, KeyCode, KeyChar, Cancel."""

    def __init__(self, ev=None):
        self.raw = ev
        self.X = getattr(ev, "x", 0)
        self.Y = getattr(ev, "y", 0)
        num = getattr(ev, "num", 0)
        self.Button = num if isinstance(num, int) else 0
        self.Delta = getattr(ev, "delta", 0)
        self.KeyCode = getattr(ev, "keysym", "")
        self.KeyChar = getattr(ev, "char", "")
        self.Cancel = False


class _ToolTip:
    def __init__(self, widget, text):
        self.widget, self.text, self.tip = widget, text, None
        widget.bind("<Enter>", self.show, add="+")
        widget.bind("<Leave>", self.hide, add="+")

    def show(self, _e=None):
        if self.tip is not None:
            return
        x = self.widget.winfo_rootx() + 12
        y = self.widget.winfo_rooty() + self.widget.winfo_height() + 4
        self.tip = tw = tk.Toplevel(self.widget)
        tw.wm_overrideredirect(True)
        tw.wm_geometry(f"+{x}+{y}")
        tk.Label(tw, text=self.text, bg="#FFFFE1", relief="solid", bd=1,
                 font=("Segoe UI", 8)).pack()

    def hide(self, _e=None):
        if self.tip is not None:
            self.tip.destroy()
            self.tip = None


class _Timer:
    """VB-like Timer: set Interval (ms) and Enabled; calls tick() every Interval."""

    def __init__(self, root, interval, tick, enabled=False):
        self.root, self.Interval, self._tick, self._job = root, interval, tick, None
        self._enabled = False
        self.Enabled = enabled

    @property
    def Enabled(self):
        return self._enabled

    @Enabled.setter
    def Enabled(self, value):
        self._enabled = bool(value)
        if self._job is not None:
            self.root.after_cancel(self._job)
            self._job = None
        if self._enabled:
            self._job = self.root.after(max(1, int(self.Interval)), self._fire)

    def Start(self):
        self.Enabled = True

    def Stop(self):
        self.Enabled = False

    def _fire(self):
        self._job = None
        if self._enabled:
            self._job = self.root.after(max(1, int(self.Interval)), self._fire)
            self._tick()


def _set_enabled(widget, on=True):
    """Enable/disable a tk or ttk widget (or a container's children)."""
    try:
        widget.configure(state="normal" if on else "disabled")
        return
    except tk.TclError:
        pass
    try:
        widget.state(["!disabled"] if on else ["disabled"])
    except (tk.TclError, AttributeError):
        for child in widget.winfo_children():
            _set_enabled(child, on)




def _rad_languages(form, embedded):
    """Languages of a form: the embedded tables + <form>.<lang>.resx.json files next to the program."""
    import glob
    out = list(embedded)
    here = os.path.dirname(os.path.abspath(__file__))
    for p in glob.glob(os.path.join(here, form + ".*.resx.json")):
        code = os.path.basename(p)[len(form) + 1:-len(".resx.json")]
        if code and code not in out:
            out.append(code)
    return out


def _rad_pick_language(available):
    """RADIDE_LANG, else language.txt next to the program, else the user's UI language ("" = default)."""
    import locale
    want = os.environ.get("RADIDE_LANG", "").strip()
    if not want:
        try:
            here = os.path.dirname(os.path.abspath(__file__))
            with open(os.path.join(here, "language.txt"), encoding="utf-8") as f:
                want = f.read().strip()
        except OSError:
            want = ""
    if not want:
        try:
            import ctypes
            want = locale.windows_locale.get(ctypes.windll.kernel32.GetUserDefaultUILanguage(), "")
        except (AttributeError, OSError, ImportError):
            want = ""
    if not want:
        try:
            want = locale.getlocale()[0] or os.environ.get("LANG", "")
        except ValueError:
            want = os.environ.get("LANG", "")
    want = want.split(".")[0].replace("-", "_").lower()
    if want in ("", "default", "(default)"):
        return ""
    low = {a.lower().replace("-", "_"): a for a in available}
    if want in low:
        return low[want]
    return low.get(want.split("_")[0], "")


def _rad_resources(form, lang, embedded):
    """The table of *lang*: embedded + <form>.<lang>.resx.json next to the program (None = no such language)."""
    if not lang:
        return None
    res = None
    if lang in embedded:
        res = dict(embedded[lang])
        res["strings"] = dict(res.get("strings") or {})
    try:
        import json
        here = os.path.dirname(os.path.abspath(__file__))
        with open(os.path.join(here, f"{form}.{lang}.resx.json"), encoding="utf-8") as f:
            ext = json.load(f)
        res = res or {"strings": {}}
        res["strings"].update(ext.get("strings") or {})
        for k in ("RightToLeft", "RightToLeftLayout"):
            if k in ext:
                res[k] = bool(ext[k])
    except (OSError, ValueError, AttributeError):
        pass
    return res

